Add 3 new exported functions (keep existing exports intact):

```ts
/**
 * Create a fully-linked artist test fixture with auth user + profile + studio_member.
 * The studio_members row carries `payouts_self_enabled` (NOT artists.payouts_self_enabled —
 * that column does not exist; per S13 migration it lives on studio_members).
 *
 * Returns IDs needed for cleanup + capability gate testing.
 */
export async function createTestArtistWithProfile(
  studioId: string,
  opts?: { payoutsSelfEnabled?: boolean },
): Promise<{ artistId: string; profileId: string; userId: string; studioMemberId: string }> {
  const supabase = testServiceClient();
  const payoutsSelfEnabled = opts?.payoutsSelfEnabled ?? false;

  // 1. auth.users via supabase admin API
  const email = `artist-${crypto.randomUUID()}@example.com`;
  const { data: userData, error: userErr } = await supabase.auth.admin.createUser({
    email,
    email_confirm: true,
    password: 'test-password-12345',
  });
  if (userErr || !userData.user) throw new Error(`createUser failed: ${userErr?.message}`);
  const userId = userData.user.id;

  // 2. profiles row (assumes existing pattern — adjust if `profiles` is auto-created via trigger)
  // Check existing helpers for whether profiles auto-creates. If yes, just SELECT the existing one.
  const { data: profileData } = await supabase
    .from('profiles')
    .select('id')
    .eq('id', userId)
    .maybeSingle();
  let profileId: string;
  if (profileData) {
    profileId = profileData.id;
  } else {
    const { data: newProfile, error: profileErr } = await supabase
      .from('profiles')
      .insert({ id: userId, full_name: `Test Artist ${userId.slice(0, 8)}` })
      .select('id')
      .single();
    if (profileErr || !newProfile) throw new Error(`profile insert failed: ${profileErr?.message}`);
    profileId = newProfile.id;
  }

  // 3. studio_members row with payouts_self_enabled (THIS is where the column lives)
  const { data: smData, error: smErr } = await supabase
    .from('studio_members')
    .insert({
      studio_id: studioId,
      user_id: userId,
      role: 'artist',
      payouts_self_enabled: payoutsSelfEnabled,
    })
    .select('id')
    .single();
  if (smErr || !smData) throw new Error(`studio_members insert failed: ${smErr?.message}`);
  const studioMemberId = smData.id;

  // 4. artists row linked to profile
  const { data: artistData, error: artistErr } = await supabase
    .from('artists')
    .insert({
      studio_id: studioId,
      profile_id: profileId,
      display_name: `Test Artist`,
    })
    .select('id')
    .single();
  if (artistErr || !artistData) throw new Error(`artists insert failed: ${artistErr?.message}`);
  const artistId = artistData.id;

  return { artistId, profileId, userId, studioMemberId };
}

/**
 * Update the artist's studio_members.payouts_self_enabled flag.
 * (Replaces the broken setArtistSelfPayouts which targeted the wrong table.)
 */
export async function setStudioMemberPayoutsSelfEnabled(
  studioId: string,
  userId: string,
  enabled: boolean,
): Promise<void> {
  const supabase = testServiceClient();
  const { error } = await supabase
    .from('studio_members')
    .update({ payouts_self_enabled: enabled })
    .eq('studio_id', studioId)
    .eq('user_id', userId);
  if (error) throw new Error(`setStudioMemberPayoutsSelfEnabled: ${error.message}`);
}

/**
 * Cleanup an artist fixture in FK-safe order.
 */
export async function cleanupArtistWithProfile(
  ids: { artistId: string; profileId: string; userId: string; studioMemberId: string },
): Promise<void> {
  const supabase = testServiceClient();
  // FK-ordered delete: connected accounts → artist → studio_member → profile → auth user
  await supabase.from('stripe_connected_accounts').delete().eq('artist_id', ids.artistId);
  await supabase.from('artists').delete().eq('id', ids.artistId);
  await supabase.from('studio_members').delete().eq('id', ids.studioMemberId);
  await supabase.from('profiles').delete().eq('id', ids.profileId);
  await supabase.auth.admin.deleteUser(ids.userId);
}
```

Add `crypto` import at top if not present: `import crypto from 'node:crypto';` (only if `crypto.randomUUID()` is used — Node 20+ has it global, may not need import).

If `testServiceClient` is named differently in helpers.ts, adapt.

If existing `createTestArtist(studioId)` is exported, keep it but add JSDoc `@deprecated Use createTestArtistWithProfile for capability gate testing.`

### 2. `tests/unit/payments/rpcs/artist-l2-payouts-enabled.test.ts`

a. Remove the local `setArtistSelfPayouts` function (it targets the wrong table).

b. Replace all `createTestArtist(studioId)` calls with `createTestArtistWithProfile(studioId, { payoutsSelfEnabled: true })`. Most tests need this — only test 1 (`self_payouts_disabled`) needs `payoutsSelfEnabled: false`.

c. For test 1 specifically:
```ts
