/**
 * RPC contract tests: artist_l2_payouts_enabled
 *
 * Coverage (8 tests — DB-gated via describe.skipIf):
 *  1. Artist payouts_self_enabled=false → enabled=false, reason='self_payouts_disabled'
 *  2. Self-enabled but no connected account → enabled=false, reason='no_connected_account'
 *  3. Account pending → enabled=false, reason='onboarding_pending'
 *  4. Account restricted → enabled=false, reason='onboarding_restricted'
 *  5. Account rejected → enabled=false, reason='onboarding_rejected'
 *  6. Account active but transfers=false → enabled=false, reason='transfers_disabled'
 *  7. Account active + transfers=true but payouts_enabled=false → enabled=false, reason='payouts_disabled'
 *  8. Account active + transfers=true + payouts_enabled=true → enabled=true, reason=null
 *
 * Track C migration must be applied for these to pass. Without DB they skip cleanly.
 *
 * payouts_self_enabled lives on studio_members (NOT artists) — see S13 migration.
 * All artist fixtures are created via createTestArtistWithProfile which wires the full
 * auth user + profile + studio_member + artists chain correctly.
 */

import { describe, it, expect, beforeAll, afterAll, afterEach } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  cleanupStudio,
  createTestArtistWithProfile,
  cleanupArtistWithProfile,
  type TestArtistWithProfile,
} from './helpers'
import {
  RPC,
  type ArtistL2PayoutsEnabledArgs,
  type ArtistL2PayoutsEnabledResult,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: artist_l2_payouts_enabled', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string

  // Track all artist fixtures created per test for cleanup
  const createdArtists: TestArtistWithProfile[] = []

  beforeAll(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
  })

  afterAll(async () => {
    await cleanupStudio(studioId)
  })

  afterEach(async () => {
    // Clean up all artist fixtures created during the test
    const toClean = createdArtists.splice(0)
    await Promise.all(toClean.map(cleanupArtistWithProfile))
  })

  // ---------------------------------------------------------------------------
  // Helper: insert an artist connected account row for test setup.
  // ---------------------------------------------------------------------------
  async function insertArtistConnectedAccount(opts: {
    artistId: string
    accountId: string
    onboardingStatus: 'pending' | 'active' | 'restricted' | 'rejected'
    chargesEnabled?: boolean
    payoutsEnabled: boolean
    transfers: boolean
  }): Promise<void> {
    const { error } = await sb.from('stripe_connected_accounts').insert({
      studio_id: studioId,
      account_id: opts.accountId,
      type: 'artist',
      artist_id: opts.artistId,
      onboarding_status: opts.onboardingStatus,
      capabilities: {
        charges_enabled: opts.chargesEnabled ?? false,
        payouts_enabled: opts.payoutsEnabled,
        transfers: opts.transfers,
        tax_reporting_us_1099_nec: false,
      },
      country: 'US',
      default_currency: 'usd',
      restricted_reason: null,
      requirements_due_by: null,
    })
    if (error) throw new Error(`insertArtistConnectedAccount failed: ${error.message}`)
  }

  it('returns enabled=false reason=self_payouts_disabled when artist has not opted in', async () => {
    const fixture = await createTestArtistWithProfile(studioId, { payoutsSelfEnabled: false })
    createdArtists.push(fixture)

    const args: ArtistL2PayoutsEnabledArgs = { artistId: fixture.artistId }

    const { data, error } = await sb.rpc(RPC.ARTIST_L2_PAYOUTS_ENABLED, {
      p_artist_id: args.artistId,
    })

    expect(error).toBeNull()
    const result = data as ArtistL2PayoutsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('self_payouts_disabled')
    expect(result.account_id).toBeNull()
    expect(result.onboarding_status).toBeNull()
  })

  it('self-enabled but no connected account → enabled=false, reason=no_connected_account', async () => {
    const fixture = await createTestArtistWithProfile(studioId, { payoutsSelfEnabled: true })
    createdArtists.push(fixture)
    // No stripe_connected_accounts row inserted for this artist

    const args: ArtistL2PayoutsEnabledArgs = { artistId: fixture.artistId }

    const { data, error } = await sb.rpc(RPC.ARTIST_L2_PAYOUTS_ENABLED, {
      p_artist_id: args.artistId,
    })

    expect(error).toBeNull()
    const result = data as ArtistL2PayoutsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('no_connected_account')
    expect(result.account_id).toBeNull()
    expect(result.onboarding_status).toBeNull()
  })

  it('account pending → enabled=false, reason=onboarding_pending', async () => {
    const fixture = await createTestArtistWithProfile(studioId, { payoutsSelfEnabled: true })
    createdArtists.push(fixture)
    const accountId = `acct_l2a_pend_${randomUUID().replace(/-/g, '').slice(0, 12)}`
    await insertArtistConnectedAccount({
      artistId: fixture.artistId,
      accountId,
      onboardingStatus: 'pending',
      payoutsEnabled: false,
      transfers: false,
    })

    const args: ArtistL2PayoutsEnabledArgs = { artistId: fixture.artistId }

    const { data, error } = await sb.rpc(RPC.ARTIST_L2_PAYOUTS_ENABLED, {
      p_artist_id: args.artistId,
    })

    expect(error).toBeNull()
    const result = data as ArtistL2PayoutsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('onboarding_pending')
    expect(result.account_id).toBe(accountId)
    expect(result.onboarding_status).toBe('pending')
  })

  it('account restricted → enabled=false, reason=onboarding_restricted', async () => {
    const fixture = await createTestArtistWithProfile(studioId, { payoutsSelfEnabled: true })
    createdArtists.push(fixture)
    const accountId = `acct_l2a_restr_${randomUUID().replace(/-/g, '').slice(0, 11)}`
    await insertArtistConnectedAccount({
      artistId: fixture.artistId,
      accountId,
      onboardingStatus: 'restricted',
      payoutsEnabled: false,
      transfers: false,
    })

    const args: ArtistL2PayoutsEnabledArgs = { artistId: fixture.artistId }

    const { data, error } = await sb.rpc(RPC.ARTIST_L2_PAYOUTS_ENABLED, {
      p_artist_id: args.artistId,
    })

    expect(error).toBeNull()
    const result = data as ArtistL2PayoutsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('onboarding_restricted')
    expect(result.onboarding_status).toBe('restricted')
  })

  it('account rejected → enabled=false, reason=onboarding_rejected', async () => {
    const fixture = await createTestArtistWithProfile(studioId, { payoutsSelfEnabled: true })
    createdArtists.push(fixture)
    const accountId = `acct_l2a_rejct_${randomUUID().replace(/-/g, '').slice(0, 11)}`
    await insertArtistConnectedAccount({
      artistId: fixture.artistId,
      accountId,
      onboardingStatus: 'rejected',
      payoutsEnabled: false,
      transfers: false,
    })

    const args: ArtistL2PayoutsEnabledArgs = { artistId: fixture.artistId }

    const { data, error } = await sb.rpc(RPC.ARTIST_L2_PAYOUTS_ENABLED, {
      p_artist_id: args.artistId,
    })

    expect(error).toBeNull()
    const result = data as ArtistL2PayoutsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('onboarding_rejected')
    expect(result.onboarding_status).toBe('rejected')
  })

  it('account active but transfers=false → enabled=false, reason=transfers_disabled', async () => {
    const fixture = await createTestArtistWithProfile(studioId, { payoutsSelfEnabled: true })
    createdArtists.push(fixture)
    const accountId = `acct_l2a_notxfr_${randomUUID().replace(/-/g, '').slice(0, 10)}`
    await insertArtistConnectedAccount({
      artistId: fixture.artistId,
      accountId,
      onboardingStatus: 'active',
      payoutsEnabled: true,
      transfers: false, // <-- transfers disabled
    })

    const args: ArtistL2PayoutsEnabledArgs = { artistId: fixture.artistId }

    const { data, error } = await sb.rpc(RPC.ARTIST_L2_PAYOUTS_ENABLED, {
      p_artist_id: args.artistId,
    })

    expect(error).toBeNull()
    const result = data as ArtistL2PayoutsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('transfers_disabled')
    expect(result.onboarding_status).toBe('active')
  })

  it('account active + transfers=true but payouts_enabled=false → enabled=false, reason=payouts_disabled', async () => {
    const fixture = await createTestArtistWithProfile(studioId, { payoutsSelfEnabled: true })
    createdArtists.push(fixture)
    const accountId = `acct_l2a_nopay_${randomUUID().replace(/-/g, '').slice(0, 11)}`
    await insertArtistConnectedAccount({
      artistId: fixture.artistId,
      accountId,
      onboardingStatus: 'active',
      payoutsEnabled: false, // <-- payouts disabled
      transfers: true,
    })

    const args: ArtistL2PayoutsEnabledArgs = { artistId: fixture.artistId }

    const { data, error } = await sb.rpc(RPC.ARTIST_L2_PAYOUTS_ENABLED, {
      p_artist_id: args.artistId,
    })

    expect(error).toBeNull()
    const result = data as ArtistL2PayoutsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('payouts_disabled')
    expect(result.onboarding_status).toBe('active')
  })

  it('account active + transfers=true + payouts_enabled=true → enabled=true, reason=null', async () => {
    const fixture = await createTestArtistWithProfile(studioId, { payoutsSelfEnabled: true })
    createdArtists.push(fixture)
    const accountId = `acct_l2a_ok_${randomUUID().replace(/-/g, '').slice(0, 13)}`
    await insertArtistConnectedAccount({
      artistId: fixture.artistId,
      accountId,
      onboardingStatus: 'active',
      chargesEnabled: true,
      payoutsEnabled: true,
      transfers: true,
    })

    const args: ArtistL2PayoutsEnabledArgs = { artistId: fixture.artistId }

    const { data, error } = await sb.rpc(RPC.ARTIST_L2_PAYOUTS_ENABLED, {
      p_artist_id: args.artistId,
    })

    expect(error).toBeNull()
    const result = data as ArtistL2PayoutsEnabledResult
    expect(result.enabled).toBe(true)
    expect(result.reason).toBeNull()
    expect(result.account_id).toBe(accountId)
    expect(result.onboarding_status).toBe('active')
  })
})

/**
 * RPC contract tests: studio_l2_payments_enabled
 *
 * Coverage (6 tests — DB-gated via describe.skipIf):
 *  1. No connected account → enabled=false, reason='no_connected_account', account_id=null
 *  2. Account pending → enabled=false, reason='onboarding_pending'
 *  3. Account restricted → enabled=false, reason='onboarding_restricted'
 *  4. Account rejected → enabled=false, reason='onboarding_rejected'
 *  5. Account active but charges_enabled=false → enabled=false, reason='charges_disabled'
 *  6. Account active + charges_enabled=true → enabled=true, reason=null, account_id populated
 *
 * Track C migration must be applied for these to pass. Without DB they skip cleanly.
 *
 * Per-test isolation: each test gets its own fresh studio (beforeEach/afterEach).
 * This avoids pollution between tests when a UNIQUE partial index on
 * stripe_connected_accounts(studio_id) WHERE type='studio' is in effect.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  type StudioL2PaymentsEnabledArgs,
  type StudioL2PaymentsEnabledResult,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: studio_l2_payments_enabled', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string

  beforeEach(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
  })

  afterEach(async () => {
    await cleanupStudio(studioId)
  })

  // ---------------------------------------------------------------------------
  // Helper: insert a connected account row directly for test setup.
  // Uses service-role client to bypass RLS. The RPC itself is tested separately.
  // ---------------------------------------------------------------------------
  async function insertConnectedAccount(opts: {
    accountId: string
    onboardingStatus: 'pending' | 'active' | 'restricted' | 'rejected'
    chargesEnabled: boolean
    payoutsEnabled?: boolean
    transfers?: boolean
  }): Promise<void> {
    const { error } = await sb.from('stripe_connected_accounts').insert({
      studio_id: studioId,
      account_id: opts.accountId,
      type: 'studio',
      artist_id: null,
      onboarding_status: opts.onboardingStatus,
      capabilities: {
        charges_enabled: opts.chargesEnabled,
        payouts_enabled: opts.payoutsEnabled ?? false,
        transfers: opts.transfers ?? false,
        tax_reporting_us_1099_nec: false,
      },
      country: 'US',
      default_currency: 'usd',
      restricted_reason: null,
      requirements_due_by: null,
    })
    if (error) throw new Error(`insertConnectedAccount failed: ${error.message}`)
  }

  it('no connected account → enabled=false, reason=no_connected_account, account_id=null', async () => {
    // Fresh per-test studio has no connected account — no extra setup needed
    const args: StudioL2PaymentsEnabledArgs = { studioId }

    const { data, error } = await sb.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
      p_studio_id: args.studioId,
    })

    expect(error).toBeNull()
    const result = data as StudioL2PaymentsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('no_connected_account')
    expect(result.account_id).toBeNull()
    expect(result.onboarding_status).toBeNull()
  })

  it('account with onboarding_status=pending → enabled=false, reason=onboarding_pending', async () => {
    const accountId = `acct_l2s_pend_${randomUUID().replace(/-/g, '').slice(0, 12)}`
    await insertConnectedAccount({
      accountId,
      onboardingStatus: 'pending',
      chargesEnabled: false,
    })

    const args: StudioL2PaymentsEnabledArgs = { studioId }

    const { data, error } = await sb.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
      p_studio_id: args.studioId,
    })

    expect(error).toBeNull()
    const result = data as StudioL2PaymentsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('onboarding_pending')
    expect(result.account_id).toBe(accountId)
    expect(result.onboarding_status).toBe('pending')
  })

  it('account with onboarding_status=restricted → enabled=false, reason=onboarding_restricted', async () => {
    const accountId = `acct_l2s_restr_${randomUUID().replace(/-/g, '').slice(0, 11)}`
    await insertConnectedAccount({
      accountId,
      onboardingStatus: 'restricted',
      chargesEnabled: false,
    })

    const args: StudioL2PaymentsEnabledArgs = { studioId }

    const { data, error } = await sb.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
      p_studio_id: args.studioId,
    })

    expect(error).toBeNull()
    const result = data as StudioL2PaymentsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('onboarding_restricted')
    expect(result.onboarding_status).toBe('restricted')
  })

  it('account with onboarding_status=rejected → enabled=false, reason=onboarding_rejected', async () => {
    const accountId = `acct_l2s_rejct_${randomUUID().replace(/-/g, '').slice(0, 11)}`
    await insertConnectedAccount({
      accountId,
      onboardingStatus: 'rejected',
      chargesEnabled: false,
    })

    const args: StudioL2PaymentsEnabledArgs = { studioId }

    const { data, error } = await sb.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
      p_studio_id: args.studioId,
    })

    expect(error).toBeNull()
    const result = data as StudioL2PaymentsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('onboarding_rejected')
    expect(result.onboarding_status).toBe('rejected')
  })

  it('account active but charges_enabled=false → enabled=false, reason=charges_disabled', async () => {
    const accountId = `acct_l2s_chgdis_${randomUUID().replace(/-/g, '').slice(0, 10)}`
    await insertConnectedAccount({
      accountId,
      onboardingStatus: 'active',
      chargesEnabled: false,
      payoutsEnabled: true,
      transfers: true,
    })

    const args: StudioL2PaymentsEnabledArgs = { studioId }

    const { data, error } = await sb.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
      p_studio_id: args.studioId,
    })

    expect(error).toBeNull()
    const result = data as StudioL2PaymentsEnabledResult
    expect(result.enabled).toBe(false)
    expect(result.reason).toBe('charges_disabled')
    expect(result.onboarding_status).toBe('active')
  })

  it('account active + charges_enabled=true → enabled=true, reason=null, account_id populated', async () => {
    const accountId = `acct_l2s_ok_${randomUUID().replace(/-/g, '').slice(0, 13)}`
    await insertConnectedAccount({
      accountId,
      onboardingStatus: 'active',
      chargesEnabled: true,
      payoutsEnabled: true,
      transfers: true,
    })

    const args: StudioL2PaymentsEnabledArgs = { studioId }

    const { data, error } = await sb.rpc(RPC.STUDIO_L2_PAYMENTS_ENABLED, {
      p_studio_id: args.studioId,
    })

    expect(error).toBeNull()
    const result = data as StudioL2PaymentsEnabledResult
    expect(result.enabled).toBe(true)
    expect(result.reason).toBeNull()
    expect(result.account_id).toBe(accountId)
    expect(result.onboarding_status).toBe('active')
  })
})

